import Mathlib.Data.Nat.Basic
import Mathlib.Data.Fin.Basic
import Mathlib.Algebra.Group.Basic

namespace NormalizationKernels

def lt16_0 : 0 < 16 := by decide
def lt16_1 : 1 < 16 := by decide
def lt16_2 : 2 < 16 := by decide
def lt16_3 : 3 < 16 := by decide
def lt16_4 : 4 < 16 := by decide
def lt16_5 : 5 < 16 := by decide
def lt16_6 : 6 < 16 := by decide
def lt16_7 : 7 < 16 := by decide
def lt16_8 : 8 < 16 := by decide
def lt16_9 : 9 < 16 := by decide
def lt16_10 : 10 < 16 := by decide
def lt16_11 : 11 < 16 := by decide
def lt16_12 : 12 < 16 := by decide
def lt16_13 : 13 < 16 := by decide
def lt16_14 : 14 < 16 := by decide
def lt16_15 : 15 < 16 := by decide

structure Vector16 (α : Type) where
  e0 : α
  e1 : α
  e2 : α
  e3 : α
  e4 : α
  e5 : α
  e6 : α
  e7 : α
  e8 : α
  e9 : α
  e10 : α
  e11 : α
  e12 : α
  e13 : α
  e14 : α
  e15 : α

def Vector16.map {α β : Type} (f : α → β) (v : Vector16 α) : Vector16 β :=
  ⟨f v.e0, f v.e1, f v.e2, f v.e3, f v.e4, f v.e5, f v.e6, f v.e7,
   f v.e8, f v.e9, f v.e10, f v.e11, f v.e12, f v.e13, f v.e14, f v.e15⟩

def Vector16.zipWith {α β γ : Type} (f : α → β → γ) (v1 : Vector16 α) (v2 : Vector16 β) : Vector16 γ :=
  ⟨f v1.e0 v2.e0, f v1.e1 v2.e1, f v1.e2 v2.e2, f v1.e3 v2.e3,
   f v1.e4 v2.e4, f v1.e5 v2.e5, f v1.e6 v2.e6, f v1.e7 v2.e7,
   f v1.e8 v2.e8, f v1.e9 v2.e9, f v1.e10 v2.e10, f v1.e11 v2.e11,
   f v1.e12 v2.e12, f v1.e13 v2.e13, f v1.e14 v2.e14, f v1.e15 v2.e15⟩

def Vector16.mul (v1 v2 : Vector16 Nat) : Vector16 Nat :=
  Vector16.zipWith Nat.mul v1 v2

theorem Vector16.mul_comm (v1 v2 : Vector16 Nat) : Vector16.mul v1 v2 = Vector16.mul v2 v1 := by
  cases v1
  cases v2
  simp [Vector16.mul, Vector16.zipWith, Nat.mul_comm]

theorem Vector16.map_map {α β γ : Type} (f : α → β) (g : β → γ) (v : Vector16 α) :
  Vector16.map g (Vector16.map f v) = Vector16.map (fun x => g (f x)) v := by
  rfl

theorem Vector16.zipWith_map_left {α β γ δ : Type} (f : α → β) (g : β → γ → δ) (v1 : Vector16 α) (v2 : Vector16 γ) :
  Vector16.zipWith g (Vector16.map f v1) v2 = Vector16.zipWith (fun x y => g (f x) y) v1 v2 := by
  rfl

def bfloat16_round_to_nearest_even (raw_f32_bits : Nat) : Nat :=
  (fun lsb =>
    (fun bias =>
      (fun rounded =>
        rounded / 65536
      ) (raw_f32_bits + bias)
    ) (32767 + lsb)
  ) ((raw_f32_bits / 65536) % 2)

theorem bfloat16_round_1_0 : bfloat16_round_to_nearest_even 1065353216 = 16256 := by rfl
theorem bfloat16_round_tie_to_even_down : bfloat16_round_to_nearest_even 1065385984 = 16256 := by rfl
theorem bfloat16_round_tie_to_even_up : bfloat16_round_to_nearest_even 1065451520 = 16258 := by rfl

def ulp_add (e1 e2 : Nat) : Nat := e1 + e2 + 1
def ulp_mul (e1 e2 : Nat) : Nat := e1 + e2 + 1
def ulp_sub (e1 e2 : Nat) : Nat := e1 + e2 + 1
def ulp_exp (e : Nat) : Nat := e + 2
def ulp_div (e1 e2 : Nat) : Nat := e1 + e2 + 1
def ulp_rsqrt (e : Nat) : Nat := e + 2

def sum16_error (v_err : Fin 16 → Nat) : Nat :=
  ulp_add (v_err ⟨0, lt16_0⟩) (
  ulp_add (v_err ⟨1, lt16_1⟩) (
  ulp_add (v_err ⟨2, lt16_2⟩) (
  ulp_add (v_err ⟨3, lt16_3⟩) (
  ulp_add (v_err ⟨4, lt16_4⟩) (
  ulp_add (v_err ⟨5, lt16_5⟩) (
  ulp_add (v_err ⟨6, lt16_6⟩) (
  ulp_add (v_err ⟨7, lt16_7⟩) (
  ulp_add (v_err ⟨8, lt16_8⟩) (
  ulp_add (v_err ⟨9, lt16_9⟩) (
  ulp_add (v_err ⟨10, lt16_10⟩) (
  ulp_add (v_err ⟨11, lt16_11⟩) (
  ulp_add (v_err ⟨12, lt16_12⟩) (
  ulp_add (v_err ⟨13, lt16_13⟩) (
  ulp_add (v_err ⟨14, lt16_14⟩) (v_err ⟨15, lt16_15⟩)
  ))))))))))))))

def softmax_element_error (x_err max_err : Nat) : Nat :=
  ulp_exp (ulp_sub x_err max_err)

def softmax_denom_error (x_err : Fin 16 → Nat) (max_err : Nat) : Nat :=
  sum16_error (fun i => softmax_element_error (x_err i) max_err)

theorem softmax_total_ulp_bound : softmax_denom_error (fun _ => 0) 0 = 63 := by rfl

def rmsnorm_denom_error (x_err : Fin 16 → Nat) (eps_err : Nat) : Nat :=
  (fun sq_err =>
    (fun sum_err =>
      (fun mean_err =>
        (fun add_eps_err =>
          ulp_rsqrt add_eps_err
        ) (ulp_add mean_err eps_err)
      ) (ulp_div sum_err 0)
    ) (sum16_error sq_err)
  ) (fun i => ulp_mul (x_err i) (x_err i))

def rmsnorm_total_error (x_err : Fin 16 → Nat) (w_err : Fin 16 → Nat) (eps_err : Nat) : Fin 16 → Nat :=
  (fun denom_err =>
    fun i => ulp_mul (ulp_mul (x_err i) denom_err) (w_err i)
  ) (rmsnorm_denom_error x_err eps_err)

theorem rmsnorm_element_0_ulp_bound : rmsnorm_total_error (fun _ => 0) (fun _ => 0) 0 ⟨0, lt16_0⟩ = 37 := by rfl

def strided_index (row col stride total_size : Nat) (h_pos : 0 < total_size) : Fin total_size :=
  ⟨(row * stride + col) % total_size, Nat.mod_lt _ h_pos⟩

theorem strided_index_correct_2_3_10 : (strided_index 2 3 10 100 (Nat.zero_lt_succ 99)).1 = 23 := by rfl

inductive ZigExpr where
  | Var (name : Nat)
  | Const (val : Nat)
  | Add (a b : ZigExpr)
  | Mul (a b : ZigExpr)

def evalZig (env : Nat → Nat) : ZigExpr → Nat
  | ZigExpr.Var n => env n
  | ZigExpr.Const v => v
  | ZigExpr.Add a b => evalZig env a + evalZig env b
  | ZigExpr.Mul a b => evalZig env a * evalZig env b

def zig_rmsnorm_inner (x w : Nat) : ZigExpr :=
  ZigExpr.Mul (ZigExpr.Mul (ZigExpr.Var x) (ZigExpr.Const 35)) (ZigExpr.Var w)

def lean_rmsnorm_inner (env : Nat → Nat) (x w : Nat) : Nat :=
  env x * 35 * env w

theorem zig_lean_isomorphism (env : Nat → Nat) (x w : Nat) :
  evalZig env (zig_rmsnorm_inner x w) = lean_rmsnorm_inner env x w := by rfl

end NormalizationKernels

const std = @import("std");

pub const V16 = @Vector(16, f32);
pub const V16_u32 = @Vector(16, u32);
pub const V16_u16 = @Vector(16, u16);

pub inline fn bf16x16_to_f32x16(v: V16_u16) V16 {
    const v_u32: V16_u32 = v;
    const shifted: V16_u32 = v_u32 << @as(V16_u32, @splat(16));
    return @bitCast(shifted);
}

pub inline fn f32x16_to_bf16x16(v: V16) V16_u16 {
    const raw: V16_u32 = @bitCast(v);
    const lsb: V16_u32 = (raw >> @as(V16_u32, @splat(16))) & @as(V16_u32, @splat(1));
    const bias: V16_u32 = @as(V16_u32, @splat(0x7FFF)) + lsb;
    const rounded: V16_u32 = raw + bias;
    const shifted: V16_u32 = rounded >> @as(V16_u32, @splat(16));
    return @truncate(shifted);
}

pub fn rmsNormForward(comptime N: usize, input: *const [N]u16, weight: *const [N]u16, output: *[N]u16, comptime eps: f32) void {
    comptime {
        if (N % 16 != 0) {
            @compileError("N must be a multiple of 16");
        }
    }
    const chunks = N / 16;
    var sum_sq: V16 = @splat(0.0);

    var i: usize = 0;
    while (i < chunks) : (i += 1) {
        const in_vec: V16_u16 = input[i * 16 .. i * 16 + 16].*;
        const f_vec = bf16x16_to_f32x16(in_vec);
        sum_sq += f_vec * f_vec;
    }

    const total_sum = @reduce(.Add, sum_sq);
    const mean_sq = total_sum / @as(f32, @floatFromInt(N));
    const denom = @sqrt(mean_sq + eps);
    const rsqrt_val = 1.0 / denom;
    const rsqrt_vec: V16 = @splat(rsqrt_val);

    var j: usize = 0;
    while (j < chunks) : (j += 1) {
        const in_vec: V16_u16 = input[j * 16 .. j * 16 + 16].*;
        const w_vec: V16_u16 = weight[j * 16 .. j * 16 + 16].*;
        const f_in = bf16x16_to_f32x16(in_vec);
        const f_w = bf16x16_to_f32x16(w_vec);
        const out_f = f_in * rsqrt_vec * f_w;
        output[j * 16 .. j * 16 + 16].* = f32x16_to_bf16x16(out_f);
    }
}

pub fn layerNormForward(comptime N: usize, input: *const [N]u16, weight: *const [N]u16, bias: *const [N]u16, output: *[N]u16, comptime eps: f32) void {
    comptime {
        if (N % 16 != 0) {
            @compileError("N must be a multiple of 16");
        }
    }
    const chunks = N / 16;
    var sum: V16 = @splat(0.0);
    var sum_sq: V16 = @splat(0.0);

    var i: usize = 0;
    while (i < chunks) : (i += 1) {
        const in_vec: V16_u16 = input[i * 16 .. i * 16 + 16].*;
        const f_vec = bf16x16_to_f32x16(in_vec);
        sum += f_vec;
        sum_sq += f_vec * f_vec;
    }

    const total_sum = @reduce(.Add, sum);
    const total_sum_sq = @reduce(.Add, sum_sq);
    const n_f32 = @as(f32, @floatFromInt(N));
    const mean = total_sum / n_f32;
    const mean_sq = total_sum_sq / n_f32;
    const variance = mean_sq - (mean * mean);
    const inv_std_val = 1.0 / @sqrt(variance + eps);

    const mean_vec: V16 = @splat(mean);
    const inv_std_vec: V16 = @splat(inv_std_val);

    var j: usize = 0;
    while (j < chunks) : (j += 1) {
        const in_vec: V16_u16 = input[j * 16 .. j * 16 + 16].*;
        const w_vec: V16_u16 = weight[j * 16 .. j * 16 + 16].*;
        const b_vec: V16_u16 = bias[j * 16 .. j * 16 + 16].*;

        const f_in = bf16x16_to_f32x16(in_vec);
        const f_w = bf16x16_to_f32x16(w_vec);
        const f_b = bf16x16_to_f32x16(b_vec);

        const centered = f_in - mean_vec;
        const normalized = centered * inv_std_vec;
        const out_f = (normalized * f_w) + f_b;

        output[j * 16 .. j * 16 + 16].* = f32x16_to_bf16x16(out_f);
    }
}

pub fn geluForward(comptime N: usize, input: *const [N]u16, output: *[N]u16) void {
    comptime {
        if (N % 16 != 0) {
            @compileError("N must be a multiple of 16");
        }
    }
    const chunks = N / 16;
    const sqrt_2_over_pi: V16 = @splat(0.7978845608028653559);
    const coeff_0_044715: V16 = @splat(0.0447149984538555145);
    const half: V16 = @splat(0.5);
    const one: V16 = @splat(1.0);

    var i: usize = 0;
    while (i < chunks) : (i += 1) {
        const in_vec: V16_u16 = input[i * 16 .. i * 16 + 16].*;
        const x = bf16x16_to_f32x16(in_vec);

        const x2 = x * x;
        const x3 = x2 * x;
        const inner = sqrt_2_over_pi * (x + (coeff_0_044715 * x3));

        const exp_2x = @exp(inner * @as(V16, @splat(2.0)));
        const tanh_val = (exp_2x - one) / (exp_2x + one);

        const out_f = half * x * (one + tanh_val);
        output[i * 16 .. i * 16 + 16].* = f32x16_to_bf16x16(out_f);
    }
}

pub fn softmaxForward(comptime N: usize, input: *const [N]u16, output: *[N]u16) void {
    comptime {
        if (N % 16 != 0) {
            @compileError("N must be a multiple of 16");
        }
    }
    const chunks = N / 16;
    var max_vec: V16 = @splat(-std.math.inf(f32));

    var i: usize = 0;
    while (i < chunks) : (i += 1) {
        const in_vec: V16_u16 = input[i * 16 .. i * 16 + 16].*;
        const f_vec = bf16x16_to_f32x16(in_vec);
        max_vec = @max(max_vec, f_vec);
    }

    const max_val = @reduce(.Max, max_vec);
    const max_splat: V16 = @splat(max_val);
    var sum_exp: V16 = @splat(0.0);

    var j: usize = 0;
    while (j < chunks) : (j += 1) {
        const in_vec: V16_u16 = input[j * 16 .. j * 16 + 16].*;
        const f_vec = bf16x16_to_f32x16(in_vec);
        const shifted = f_vec - max_splat;
        const exp_vec = @exp(shifted);
        sum_exp += exp_vec;
    }

    const total_sum_exp = @reduce(.Add, sum_exp);
    const inv_sum_exp: V16 = @splat(1.0 / total_sum_exp);

    var k: usize = 0;
    while (k < chunks) : (k += 1) {
        const in_vec: V16_u16 = input[k * 16 .. k * 16 + 16].*;
        const f_vec = bf16x16_to_f32x16(in_vec);
        const shifted = f_vec - max_splat;
        const exp_vec = @exp(shifted);
        const out_f = exp_vec * inv_sum_exp;
        output[k * 16 .. k * 16 + 16].* = f32x16_to_bf16x16(out_f);
    }
}

pub fn rmsNormBackward(comptime N: usize, grad_output: *const [N]u16, input: *const [N]u16, weight: *const [N]u16, grad_input: *[N]u16, grad_weight: *[N]u16, comptime eps: f32) void {
    comptime {
        if (N % 16 != 0) {
            @compileError("N must be a multiple of 16");
        }
    }
    const chunks = N / 16;
    var sum_sq: V16 = @splat(0.0);

    var i: usize = 0;
    while (i < chunks) : (i += 1) {
        const in_vec: V16_u16 = input[i * 16 .. i * 16 + 16].*;
        const f_vec = bf16x16_to_f32x16(in_vec);
        sum_sq += f_vec * f_vec;
    }

    const total_sum = @reduce(.Add, sum_sq);
    const n_f32 = @as(f32, @floatFromInt(N));
    const mean_sq = total_sum / n_f32;
    const denom = @sqrt(mean_sq + eps);
    const rsqrt_val = 1.0 / denom;
    const rsqrt_cubed_val = rsqrt_val * rsqrt_val * rsqrt_val;

    const rsqrt_vec: V16 = @splat(rsqrt_val);
    const rsqrt_cubed_vec: V16 = @splat(rsqrt_cubed_val);
    const n_inv_vec: V16 = @splat(1.0 / n_f32);

    var sum_gwx: V16 = @splat(0.0);

    var j: usize = 0;
    while (j < chunks) : (j += 1) {
        const g_vec: V16_u16 = grad_output[j * 16 .. j * 16 + 16].*;
        const w_vec: V16_u16 = weight[j * 16 .. j * 16 + 16].*;
        const x_vec: V16_u16 = input[j * 16 .. j * 16 + 16].*;

        const f_g = bf16x16_to_f32x16(g_vec);
        const f_w = bf16x16_to_f32x16(w_vec);
        const f_x = bf16x16_to_f32x16(x_vec);

        sum_gwx += f_g * f_w * f_x;
    }

    const total_sum_gwx = @reduce(.Add, sum_gwx);
    const sum_gwx_vec: V16 = @splat(total_sum_gwx);

    var k: usize = 0;
    while (k < chunks) : (k += 1) {
        const g_vec: V16_u16 = grad_output[k * 16 .. k * 16 + 16].*;
        const w_vec: V16_u16 = weight[k * 16 .. k * 16 + 16].*;
        const x_vec: V16_u16 = input[k * 16 .. k * 16 + 16].*;

        const f_g = bf16x16_to_f32x16(g_vec);
        const f_w = bf16x16_to_f32x16(w_vec);
        const f_x = bf16x16_to_f32x16(x_vec);

        const term1 = f_w * rsqrt_vec * f_g;
        const term2 = f_x * sum_gwx_vec * rsqrt_cubed_vec * n_inv_vec;
        const grad_in_f = term1 - term2;

        const grad_w_f = f_g * f_x * rsqrt_vec;

        grad_input[k * 16 .. k * 16 + 16].* = f32x16_to_bf16x16(grad_in_f);
        grad_weight[k * 16 .. k * 16 + 16].* = f32x16_to_bf16x16(grad_w_f);
    }
}

pub fn layerNormBackward(comptime N: usize, grad_output: *const [N]u16, input: *const [N]u16, weight: *const [N]u16, grad_input: *[N]u16, grad_weight: *[N]u16, grad_bias: *[N]u16, comptime eps: f32) void {
    comptime {
        if (N % 16 != 0) {
            @compileError("N must be a multiple of 16");
        }
    }
    const chunks = N / 16;
    var sum: V16 = @splat(0.0);
    var sum_sq: V16 = @splat(0.0);

    var i: usize = 0;
    while (i < chunks) : (i += 1) {
        const in_vec: V16_u16 = input[i * 16 .. i * 16 + 16].*;
        const f_vec = bf16x16_to_f32x16(in_vec);
        sum += f_vec;
        sum_sq += f_vec * f_vec;
    }

    const total_sum = @reduce(.Add, sum);
    const total_sum_sq = @reduce(.Add, sum_sq);
    const n_f32 = @as(f32, @floatFromInt(N));
    const mean = total_sum / n_f32;
    const mean_sq = total_sum_sq / n_f32;
    const variance = mean_sq - (mean * mean);
    const inv_std_val = 1.0 / @sqrt(variance + eps);

    const mean_vec: V16 = @splat(mean);
    const inv_std_vec: V16 = @splat(inv_std_val);
    const n_inv_vec: V16 = @splat(1.0 / n_f32);

    var sum_grad: V16 = @splat(0.0);
    var sum_grad_centered: V16 = @splat(0.0);

    var j: usize = 0;
    while (j < chunks) : (j += 1) {
        const x_vec: V16_u16 = input[j * 16 .. j * 16 + 16].*;
        const g_vec: V16_u16 = grad_output[j * 16 .. j * 16 + 16].*;
        const w_vec: V16_u16 = weight[j * 16 .. j * 16 + 16].*;

        const f_x = bf16x16_to_f32x16(x_vec);
        const f_g = bf16x16_to_f32x16(g_vec);
        const f_w = bf16x16_to_f32x16(w_vec);

        const centered = f_x - mean_vec;
        const grad_centered = f_g * f_w;

        sum_grad += grad_centered;
        sum_grad_centered += grad_centered * centered;
    }

    const total_sum_grad = @reduce(.Add, sum_grad);
    const total_sum_grad_centered = @reduce(.Add, sum_grad_centered);

    const sum_grad_vec: V16 = @splat(total_sum_grad);
    const sum_grad_centered_vec: V16 = @splat(total_sum_grad_centered);
    const inv_std_cubed_vec = inv_std_vec * inv_std_vec * inv_std_vec;

    var k: usize = 0;
    while (k < chunks) : (k += 1) {
        const x_vec: V16_u16 = input[k * 16 .. k * 16 + 16].*;
        const g_vec: V16_u16 = grad_output[k * 16 .. k * 16 + 16].*;
        const w_vec: V16_u16 = weight[k * 16 .. k * 16 + 16].*;

        const f_x = bf16x16_to_f32x16(x_vec);
        const f_g = bf16x16_to_f32x16(g_vec);
        const f_w = bf16x16_to_f32x16(w_vec);

        const centered = f_x - mean_vec;

        const term1 = f_g * f_w * inv_std_vec;
        const term2 = sum_grad_vec * inv_std_vec * n_inv_vec;
        const term3 = centered * sum_grad_centered_vec * inv_std_cubed_vec * n_inv_vec;

        const grad_in_f = term1 - term2 - term3;
        const grad_w_f = f_g * centered * inv_std_vec;
        const grad_b_f = f_g;

        grad_input[k * 16 .. k * 16 + 16].* = f32x16_to_bf16x16(grad_in_f);
        grad_weight[k * 16 .. k * 16 + 16].* = f32x16_to_bf16x16(grad_w_f);
        grad_bias[k * 16 .. k * 16 + 16].* = f32x16_to_bf16x16(grad_b_f);
    }
}

pub fn softmaxBackward(comptime N: usize, grad_output: *const [N]u16, output: *const [N]u16, grad_input: *[N]u16) void {
    comptime {
        if (N % 16 != 0) {
            @compileError("N must be a multiple of 16");
        }
    }
    const chunks = N / 16;
    var dot_product_vec: V16 = @splat(0.0);

    var i: usize = 0;
    while (i < chunks) : (i += 1) {
        const s_vec: V16_u16 = output[i * 16 .. i * 16 + 16].*;
        const g_vec: V16_u16 = grad_output[i * 16 .. i * 16 + 16].*;

        const f_s = bf16x16_to_f32x16(s_vec);
        const f_g = bf16x16_to_f32x16(g_vec);

        dot_product_vec += f_s * f_g;
    }

    const total_dot_product = @reduce(.Add, dot_product_vec);
    const dot_splat: V16 = @splat(total_dot_product);

    var j: usize = 0;
    while (j < chunks) : (j += 1) {
        const s_vec: V16_u16 = output[j * 16 .. j * 16 + 16].*;
        const g_vec: V16_u16 = grad_output[j * 16 .. j * 16 + 16].*;

        const f_s = bf16x16_to_f32x16(s_vec);
        const f_g = bf16x16_to_f32x16(g_vec);

        const grad_in_f = f_s * (f_g - dot_splat);
