const std = @import("std");

pub const V16 = @Vector(16, f32);
pub const V16_u32 = @Vector(16, u32);
pub const V16_u16 = @Vector(16, u16);

pub inline fn bf16x16_to_f32x16(v: V16_u16) V16 {
    const v_u32: V16_u32 = v;
    const shifted: V16_u32 = v_u32 << @as(V16_u32, @splat(16));
    return @bitCast(shifted);
}

pub inline fn f32x16_to_bf16x16(v: V16) V16_u16 {
    const raw: V16_u32 = @bitCast(v);
    const lsb: V16_u32 = (raw >> @as(V16_u32, @splat(16))) & @as(V16_u32, @splat(1));
    const bias: V16_u32 = @as(V16_u32, @splat(0x7FFF)) + lsb;
    const rounded: V16_u32 = raw + bias;
    const shifted: V16_u32 = rounded >> @as(V16_u32, @splat(16));
    return @truncate(shifted);
}

pub fn rmsNormForward(comptime N: usize, input: *const [N]u16, weight: *const [N]u16, output: *[N]u16, comptime eps: f32) void {
    const chunks = N / 16;
    var sum_sq: V16 = @splat(0.0);

    comptime var i = 0;
    inline while (i < chunks) : (i += 1) {
        const in_vec: V16_u16 = input[i * 16 .. i * 16 + 16].*;
        const f_vec = bf16x16_to_f32x16(in_vec);
        sum_sq += f_vec * f_vec;
    }

    const total_sum = @reduce(.Add, sum_sq);
    const mean_sq = total_sum / @as(f32, @floatFromInt(N));
    const denom = @sqrt(mean_sq + eps);
    const rsqrt_val = 1.0 / denom;
    const rsqrt_vec: V16 = @splat(rsqrt_val);

    comptime var j = 0;
    inline while (j < chunks) : (j += 1) {
        const in_vec: V16_u16 = input[j * 16 .. j * 16 + 16].*;
        const w_vec: V16_u16 = weight[j * 16 .. j * 16 + 16].*;
        const f_in = bf16x16_to_f32x16(in_vec);
        const f_w = bf16x16_to_f32x16(w_vec);
        const out_f = f_in * rsqrt_vec * f_w;
        const out_bf = f32x16_to_bf16x16(out_f);
        output[j * 16 .. j * 16 + 16].* = out_bf;
    }
}

pub fn layerNormForward(comptime N: usize, input: *const [N]u16, weight: *const [N]u16, bias: *const [N]u16, output: *[N]u16, comptime eps: f32) void {
    const chunks = N / 16;
    var sum: V16 = @splat(0.0);
    var sum_sq: V16 = @splat(0.0);

    comptime var i = 0;
    inline while (i < chunks) : (i += 1) {
        const in_vec: V16_u16 = input[i * 16 .. i * 16 + 16].*;
        const f_vec = bf16x16_to_f32x16(in_vec);
        sum += f_vec;
        sum_sq += f_vec * f_vec;
    }

    const total_sum = @reduce(.Add, sum);
    const total_sum_sq = @reduce(.Add, sum_sq);
    const n_f32 = @as(f32, @floatFromInt(N));
    const mean = total_sum / n_f32;
    const mean_sq = total_sum_sq / n_f32;
    const variance = mean_sq - (mean * mean);
    const inv_std_val = 1.0 / @sqrt(variance + eps);

    const mean_vec: V16 = @splat(mean);
    const inv_std_vec: V16 = @splat(inv_std_val);

    comptime var j = 0;
    inline while (j < chunks) : (j += 1) {
        const in_vec: V16_u16 = input[j * 16 .. j * 16 + 16].*;
        const w_vec: V16_u16 = weight[j * 16 .. j * 16 + 16].*;
        const b_vec: V16_u16 = bias[j * 16 .. j * 16 + 16].*;

        const f_in = bf16x16_to_f32x16(in_vec);
        const f_w = bf16x16_to_f32x16(w_vec);
        const f_b = bf16x16_to_f32x16(b_vec);

        const centered = f_in - mean_vec;
        const normalized = centered * inv_std_vec;
        const out_f = (normalized * f_w) + f_b;

        const out_bf = f32x16_to_bf16x16(out_f);
        output[j * 16 .. j * 16 + 16].* = out_bf;
    }
}

pub fn geluForward(comptime N: usize, input: *const [N]u16, output: *[N]u16) void {
    const chunks = N / 16;
