    const coeff_0_044715: V16 = @splat(0.0447149984538555145);
    const half: V16 = @splat(0.5);
    const one: V16 = @splat(1.0);

    comptime var i = 0;
    inline while (i < chunks) : (i += 1) {
        const in_vec: V16_u16 = input[i * 16 .. i * 16 + 16].*;
        const x = bf16x16_to_f32x16(in_vec);

        const x2 = x * x;
        const x3 = x2 * x;
        const inner = sqrt_2_over_pi * (x + (coeff_0_044715 * x3));

        const exp_2x = @exp(inner * @as(V16, @splat(2.0)));
        const tanh_val = (exp_2x - one) / (exp_2x + one);

        const out_f = half * x * (one + tanh_val);
        const out_bf = f32x16_to_bf16x16(out_f);
        output[i * 16 .. i * 16 + 16].* = out_bf;
    }
