    inline while (i < chunks) : (i += 1) {
        const in_vec: V16_u16 = input[i * 16 .. i * 16 + 16].*;
        const f_vec = bf16x16_to_f32x16(in_vec);
        sum += f_vec;
        sum_sq += f_vec * f_vec;
    }

    const total_sum = @reduce(.Add, sum);
    const total_sum_sq = @reduce(.Add, sum_sq);
    const n_f32 = @as(f32, @floatFromInt(N));
    const mean = total_sum / n_f32;
    const mean_sq = total_sum_sq / n_f32;
    const variance = mean_sq - (mean * mean);
    const inv_std_val = 1.0 / @sqrt(variance + eps);

    const mean_vec: V16 = @splat(mean);
    const inv_std_vec: V16 = @splat(inv_std_val);
    const n_inv_vec: V16 = @splat(1.0 / n_f32);

    var sum_grad: V16 = @splat(0.0);
    var sum_grad_centered: V16 = @splat(0.0);

    comptime var j = 0;
    inline while (j < chunks) : (j += 1) {
        const x_vec: V16_u16 = input[j * 16 .. j * 16 + 16].*;
        const g_vec: V16_u16 = grad_output[j * 16 .. j * 16 + 16].*;
        const w_vec: V16_u16 = weight[j * 16 .. j * 16 + 16].*;

        const f_x = bf16x16_to_f32x16(x_vec);
        const f_g = bf16x16_to_f32x16(g_vec);
        const f_w = bf16x16_to_f32x16(w_vec);

        const centered = f_x - mean_vec;
        const grad_centered = f_g * f_w;

        sum_grad += grad_centered;
        sum_grad_centered += grad_centered * centered;
    }

    const total_sum_grad = @reduce(.Add, sum_grad);
    const total_sum_grad_centered = @reduce(.Add, sum_grad_centered);

    const sum_grad_vec: V16 = @splat(total_sum_grad);
    const sum_grad_centered_vec: V16 = @splat(total_sum_grad_centered);
    const inv_std_cubed_vec = inv_std_vec * inv_std_vec * inv_std_vec;

    comptime var k = 0;
    inline while (k < chunks) : (k += 1) {
        const x_vec: V16_u16 = input[k * 16 .. k * 16 + 16].*;
        const g_vec: V16_u16 = grad_output[k * 16 .. k * 16 + 16].*;
        const w_vec: V16_u16 = weight[k * 16 .. k * 16 + 16].*;

        const f_x = bf16x16_to_f32x16(x_vec);
        const f_g = bf16x16_to_f32x16(g_vec);
        const f_w = bf16x16_to_f32x16(w_vec);

        const centered = f_x - mean_vec;

        const term1 = f_g * f_w * inv_std_vec;
        const term2 = sum_grad_vec * inv_std_vec * n_inv_vec;
        const term3 = centered * sum_grad_centered_vec * inv_std_cubed_vec * n_inv_vec;

        const grad_in_f = term1 - term2 - term3;
        const grad_w_f = f_g * centered * inv_std_vec;
        const grad_b_f = f_g;

        grad_input[k * 16 .. k * 16 + 16].* = f32x16_to_bf16x16(grad_in_f);
        grad_weight[k * 16 .. k * 16 + 16].* = f32x16_to_bf16x16(grad_w_f);
        grad_bias[k * 16 .. k * 16 + 16].* = f32x16_to_bf16x16(grad_b_f);
    }
}

pub fn softmaxBackward(comptime N: usize, grad_output: *const [N]u16, output: *const [N]u16, grad_input: *[N]u16) void {
    const chunks = N / 16;
    var dot_product_vec: V16 = @splat(0.0);

    comptime var i = 0;
    inline while (i < chunks) : (i += 1) {
        const s_vec: V16_u16 = output[i * 16 .. i * 16 + 16].*;
        const g_vec: V16_u16 = grad_output[i * 16 .. i * 16 + 16].*;

        const f_s = bf16x16_to_f32x16(s_vec);
        const f_g = bf16x16_to_f32x16(g_vec);

        dot_product_vec += f_s * f_g;
    }

    const total_dot_product = @reduce(.Add, dot_product_vec);
    const dot_splat: V16 = @splat(total_dot_product);

    comptime var j = 0;
    inline while (j < chunks) : (j += 1) {
        const s_vec: V16_u16 = output[j * 16 .. j * 16 + 16].*;
        const g_vec: V16_u16 = grad_output[j * 16 .. j * 16 + 16].*;

        const f_s = bf16x16_to_f32x16(s_vec);
        const f_g = bf16x16_to_f32x16(g_vec);

        const grad_in_f = f_s * (f_g - dot_splat);
        grad_input[j * 16 .. j * 16 + 16].* = f32x16_to_bf16x16(grad_in_f);
    }
}

pub fn geluBackward(comptime N: usize, grad_output: *const [N]u16, input: *const [N]u16, grad_input: *[N]u16) void {
    const chunks = N / 16;
    const sqrt_2_over_pi: V16 = @splat(0.7978845608028653559);
    const coeff_0_044715: V16 = @splat(0.0447149984538555145);
    const coeff_3_044715: V16 = @splat(0.1341449953616565435);
    const half: V16 = @splat(0.5);
    const one: V16 = @splat(1.0);

    comptime var i = 0;
    inline while (i < chunks) : (i += 1) {
        const x_vec: V16_u16 = input[i * 16 .. i * 16 + 16].*;
        const g_vec: V16_u16 = grad_output[i * 16 .. i * 16 + 16].*;

        const x = bf16x16_to_f32x16(x_vec);
        const g = bf16x16_to_f32x16(g_vec);

        const x2 = x * x;
        const x3 = x2 * x;
        const tanh_arg = sqrt_2_over_pi * (x + (coeff_0_044715 * x3));

        const exp_2x = @exp(tanh_arg * @as(V16, @splat(2.0)));
        const tanh_val = (exp_2x - one) / (exp_2x + one);
        const sech_sq = one - (tanh_val * tanh_val);
        const inner_deriv = sqrt_2_over_pi * (one + (coeff_3_044715 * x2));

        const deriv = half * (one + tanh_val) + half * x * sech_sq * inner_deriv;
        const grad_in_f = g * deriv;

        grad_input[i * 16 .. i * 16 + 16].* = f32x16_to_bf16x16(grad_in_f);
    }
}
